// Sink-independent helpers for the video-formats tests: loading, the expected values (oracle), patch
// comparison and transform detection, shared by the Canvas 2D, WebGL and WebGPU tests.
//
// Needs video-formats-manifest.js (generated by generate-video-formats.py) loaded first.
//
// Terms:
// * pattern: pattern v3, a 5x3 grid of flat patches (layouts in the manifest). Each video encodes it,
//   possibly with a display transform (rotation/mirror metadata).
// * sink: the web API that consumes a video frame and turns it into pixels: Canvas 2D (drawImage,
//   createPattern, createImageBitmap into a canvas), WebGL (texImage2D, texSubImage2D, texImage3D,
//   texSubImage3D into a texture) or WebGPU (importExternalTexture, copyExternalImageToTexture into a
//   texture). Each sink has an adapter file that does the draw or upload and reads the result back, so
//   the same oracle checks every sink.
// * readback: {width, height, data} with 8-bit RGBA, row 0 = top. Every sink returns its result as a
//   readback, so the oracle and the checks below are shared by all sinks.
// * transform: one of TRANSFORMS. Mirror (horizontal) first, then rotate clockwise.
//
// Sink interface (one file per sink, in each suite's resources directory, e.g.
// context2d/video-formats/resources/2d-video-sink.js and webgl/video-formats/resources/webgl-video-sink.js):
//   sink.name                                  e.g. "2d"
//   sink.variants                              destination variants, each {name, ...}
//   sink.sourceKinds                           the source kinds the sink accepts ("video", "videoframe", ...)
//   sink.oracleColorSpace(variant, options)    the manifest value set the result must match:
//                                              "native" | "srgb" | "displayP3" | "displayP3ReadAsSrgb"
//   await sink.createSource(kind, video, options)
//                                              -> {kind, label, image, width, height, close()}
//   await sink.render(source, variant, options)
//                                              -> {readback, size: {width, height}, info}
//                                              (size: the observed size of the drawn/uploaded image;
//                                              info: sink-specific, e.g. the WebGL upload record)
// Scenario code: render, then VideoFormats.checkPatches(result.readback,
//   VideoFormats.expectedPatches(videoInfo, {colorSpace: sink.oracleColorSpace(variant), ...})).

"use strict";

var VideoFormats = (() => {
    const manifest = window.videoFormatsManifest;
    const scriptURL = document.currentScript ? document.currentScript.src : location.href;
    const baseURL = new URL(".", scriptURL);

    // Matrices act on centred coordinates, y down: [a, b, c, d] maps (x, y) to (a x + b y, c x + d y).
    const TRANSFORMS = {
        "none": [1, 0, 0, 1],
        "rotate90": [0, -1, 1, 0],
        "rotate180": [-1, 0, 0, -1],
        "rotate270": [0, 1, -1, 0],
        "mirror": [-1, 0, 0, 1],
        "mirror+rotate90": [0, -1, -1, 0],
        "mirror+rotate180": [1, 0, 0, -1],
        "mirror+rotate270": [0, 1, 1, 0],
    };
    const transformNames = Object.keys(TRANSFORMS);

    function transformName(m)
    {
        for (const name of transformNames) {
            const t = TRANSFORMS[name];
            if (t.every((v, i) => v === m[i]))
                return name;
        }
        throw new Error("not a transform: " + m);
    }

    // The transform that applies `first`, then `second`.
    function composeTransforms(first, second)
    {
        const [a, b, c, d] = TRANSFORMS[first];
        const [e, f, g, h] = TRANSFORMS[second];
        return transformName([e * a + f * c, e * b + f * d, g * a + h * c, g * b + h * d]);
    }

    // Spec order for WebCodecs VideoFrame rotation/flip (rotate clockwise, then flip horizontally).
    function transformFromRotationAndFlip(rotation, flip)
    {
        const rotate = rotation ? "rotate" + rotation : "none";
        return flip ? composeTransforms(rotate, "mirror") : rotate;
    }

    function swapsAxes(transform)
    {
        return TRANSFORMS[transform][1] !== 0;
    }

    function transformedSize(transform, width, height)
    {
        return swapsAxes(transform) ? { width: height, height: width } : { width, height };
    }

    function mapPoint(transform, width, height, x, y)
    {
        const [a, b, c, d] = TRANSFORMS[transform];
        const cx = x - width / 2;
        const cy = y - height / 2;
        const size = transformedSize(transform, width, height);
        return { x: a * cx + b * cy + size.width / 2, y: c * cx + d * cy + size.height / 2 };
    }

    function mapRect(transform, width, height, rect)
    {
        const p = mapPoint(transform, width, height, rect.x, rect.y);
        const q = mapPoint(transform, width, height, rect.x + rect.w, rect.y + rect.h);
        return { x: Math.min(p.x, q.x), y: Math.min(p.y, q.y), w: Math.abs(q.x - p.x), h: Math.abs(q.y - p.y) };
    }

    function intersect(a, b)
    {
        const x = Math.max(a.x, b.x);
        const y = Math.max(a.y, b.y);
        const r = Math.min(a.x + a.w, b.x + b.w);
        const bottom = Math.min(a.y + a.h, b.y + b.h);
        if (r <= x || bottom <= y)
            return null;
        return { x, y, w: r - x, h: bottom - y };
    }

    // ---- Manifest access ----

    function videoInfo(name)
    {
        const info = manifest.videos[name];
        if (!info)
            throw new Error("video not in the manifest: " + name);
        return info;
    }

    function videoNames(filter)
    {
        return Object.keys(manifest.videos).filter(name => !filter || filter(manifest.videos[name], name));
    }

    function videoURL(name)
    {
        return new URL(name, baseURL).href;
    }

    function layoutOf(info)
    {
        return manifest.layouts[info.layout];
    }

    function cellColor(cellName, frame)
    {
        if (cellName.startsWith("bit")) {
            const bit = Number(cellName.substring(3));
            return ((frame % 8) >> bit) & 1 ? "white" : "black";
        }
        return cellName;
    }

    function cellAlpha(info, cellName)
    {
        if (!info.alpha)
            return 255;
        return cellName in manifest.alpha ? manifest.alpha[cellName] : 255;
    }

    // Default per-channel tolerance for patch averages. Colour-managed oracles get 2 more.
    function defaultTolerance(info, colorSpace)
    {
        let tolerance = info.bitDepth > 8 ? 4 : 3;
        if (info.managed === "measured")
            tolerance = 5;
        if (colorSpace && colorSpace !== "native")
            tolerance += 2;
        return tolerance;
    }

    // ---- Loading and frames ----

    function fetchArrayBuffer(url)
    {
        return new Promise((resolve, reject) => {
            const xhr = new XMLHttpRequest();
            xhr.open("GET", url);
            xhr.responseType = "arraybuffer";
            xhr.onload = () => resolve(xhr.response);
            xhr.onerror = () => reject(new Error("failed to load " + url));
            xhr.send();
        });
    }

    function waitForEvent(target, type, timeout)
    {
        return new Promise((resolve, reject) => {
            let timer;
            const listener = event => {
                clearTimeout(timer);
                resolve(event);
            };
            target.addEventListener(type, listener, { once: true });
            if (timeout) {
                timer = setTimeout(() => {
                    target.removeEventListener(type, listener);
                    reject(new Error(`timed out waiting for ${type}`));
                }, timeout);
            }
        });
    }

    function waitForVideoFrame(video, timeout)
    {
        return new Promise((resolve, reject) => {
            let timer;
            video.requestVideoFrameCallback((now, metadata) => {
                clearTimeout(timer);
                resolve(metadata);
            });
            if (timeout)
                timer = setTimeout(() => reject(new Error("timed out waiting for a video frame")), timeout);
        });
    }

    async function attachMediaSource(video, name, info, options)
    {
        const mediaSource = new MediaSource();
        video.src = URL.createObjectURL(mediaSource);
        await waitForEvent(mediaSource, "sourceopen", 5000);
        const buffer = mediaSource.addSourceBuffer(info.mimeType);
        const data = await fetchArrayBuffer(videoURL(name));
        buffer.appendBuffer(options.initOnly ? data.slice(0, options.initOnly) : data);
        await waitForEvent(buffer, "updateend", 5000);
        if (!options.initOnly)
            mediaSource.endOfStream();
        return mediaSource;
    }

    // A paused <video> showing frame 0. options.mse: play through MediaSource.
    async function loadVideo(name, options = { })
    {
        const info = videoInfo(name);
        const video = options.video || document.createElement("video");
        video.dataset.videoFormatsName = name;
        video.muted = true;
        video.playsInline = true;
        video.preload = "auto";
        if (options.mse) {
            if (!window.MediaSource || !MediaSource.isTypeSupported(info.mimeType))
                throw new Error(`MediaSource does not support ${info.mimeType}`);
            await attachMediaSource(video, name, info, options);
        } else
            video.src = videoURL(name);
        const framePromise = waitForVideoFrame(video, 5000);
        await video.play();
        await framePromise;
        video.pause();
        await seekToFrame(video, 0, info);
        return video;
    }

    // Waits until the video stops presenting new frames: no requestVideoFrameCallback for `quiet` ms
    // (at most `limit` ms). A paused video can keep presenting frames for a while after a seek or
    // after pause(), and drawing during that time races with it.
    async function waitForStableFrame(video, quiet = 250, limit = 3000)
    {
        const end = performance.now() + limit;
        while (performance.now() < end) {
            const presented = await Promise.race([
                waitForVideoFrame(video).then(() => true),
                new Promise(resolve => setTimeout(() => resolve(false), quiet)),
            ]);
            if (!presented)
                return;
        }
    }

    // Stops a video and releases its media resources (decoders, frames).
    function releaseVideo(video)
    {
        video.pause();
        video.removeAttribute("src");
        video.srcObject = null;
        video.load();
    }

    // Shows frame n of a paused video.
    async function seekToFrame(video, n, info)
    {
        info = info || (video.dataset.videoFormatsName && videoInfo(video.dataset.videoFormatsName));
        const fps = info ? info.fps : manifest.fps;
        const start = info ? info.startTime : 0;
        const target = start + (n + 0.5) / fps;
        if (Math.abs(video.currentTime - target) < 1e-6 && video.readyState >= HTMLMediaElement.HAVE_CURRENT_DATA) {
            await waitForStableFrame(video);
            return;
        }
        const seeked = waitForEvent(video, "seeked", 5000);
        const frame = waitForVideoFrame(video, 1000).catch(() => null);
        video.currentTime = target;
        await seeked;
        // The callback is not guaranteed for a paused seek; callers check the frame counter instead.
        await frame;
        await waitForStableFrame(video);
    }

    // ---- Oracle ----

    function colorValue(info, color, colorSpace, measured)
    {
        if (measured && measured[color])
            return measured[color];
        const entry = info.colors[color];
        const value = entry[colorSpace];
        if (!value)
            return null;
        return value;
    }

    // Expected patch values and where to sample them.
    // options:
    //   colorSpace: "native" | "srgb" | "displayP3" | "displayP3ReadAsSrgb" | "nativeInDisplayP3"
    //               (default "native")
    //   frame: frame number, for the counter bits (default 0)
    //   transform: pattern -> drawn image (default: the video's display transform, info.transform)
    //   subRect: {x, y, w, h} source sub-rectangle in display (transformed) coordinates (default: all)
    //   dest: {x, y, w, h} where subRect lands in the readback (default {0, 0, subRect.w, subRect.h})
    //   flipY: the drawn image is upside down within dest
    //   clip: {x, y, w, h} visible readback area (default: dest)
    //   alpha: "straight" (unpremultiplied source alpha), "opaque" (alpha 255, colour composited
    //          over `background`, black by default), "premultiplied"
    //   background: [r, g, b] composited under the frame with source-over; the result is opaque
    //   measured: {color: [r, g, b]} measured values for colours without a defined oracle
    // Returns [{cell, color, rect, expected: [r, g, b, a], checkColor}], rects in readback pixels.
    function expectedPatches(info, options = { })
    {
        const colorSpace = options.colorSpace || "native";
        const frame = options.frame || 0;
        const transform = options.transform || info.transform;
        const layout = layoutOf(info);
        const display = transformedSize(transform, layout.width, layout.height);
        const subRect = options.subRect || { x: 0, y: 0, w: display.width, h: display.height };
        const dest = options.dest || { x: 0, y: 0, w: subRect.w, h: subRect.h };
        const clip = options.clip || dest;
        const scaleX = dest.w / subRect.w;
        const scaleY = dest.h / subRect.h;
        const result = [];
        for (const cell of layout.cells) {
            const size = Math.min(16, Math.floor(Math.min(cell.w, cell.h) / 4));
            const inPattern = {
                x: cell.x + Math.floor((cell.w - size) / 2),
                y: cell.y + Math.floor((cell.h - size) / 2),
                w: size,
                h: size,
            };
            let rect = intersect(mapRect(transform, layout.width, layout.height, inPattern), subRect);
            if (!rect)
                continue;
            rect = { x: (rect.x - subRect.x) * scaleX, y: (rect.y - subRect.y) * scaleY, w: rect.w * scaleX, h: rect.h * scaleY };
            if (options.flipY)
                rect.y = dest.h - rect.y - rect.h;
            rect.x += dest.x;
            rect.y += dest.y;
            rect = intersect(rect, clip);
            if (!rect)
                continue;
            const x0 = Math.ceil(rect.x - 1e-6);
            const y0 = Math.ceil(rect.y - 1e-6);
            const x1 = Math.floor(rect.x + rect.w + 1e-6);
            const y1 = Math.floor(rect.y + rect.h + 1e-6);
            if (x1 <= x0 || y1 <= y0)
                continue;
            const color = cellColor(cell.name, frame);
            const value = colorValue(info, color, colorSpace, options.measured);
            const alpha = cellAlpha(info, cell.name);
            let expected = value ? [value[0], value[1], value[2], alpha] : null;
            let checkColor = !!value;
            if (expected) {
                const a = alpha / 255;
                if (options.background) {
                    const bg = options.background;
                    expected = [0, 1, 2].map(i => expected[i] * a + bg[i] * (1 - a)).concat([255]);
                } else if (options.alpha === "opaque")
                    expected = [expected[0] * a, expected[1] * a, expected[2] * a, 255];
                else if (options.alpha === "premultiplied")
                    expected = [expected[0] * a, expected[1] * a, expected[2] * a, alpha];
                else if (alpha === 0)
                    checkColor = false;
            }
            result.push({ cell: cell.name, color, rect: { x: x0, y: y0, w: x1 - x0, h: y1 - y0 }, expected, checkColor, alpha });
        }
        return result;
    }

    function samplePatch(readback, rect)
    {
        const sum = [0, 0, 0, 0];
        for (let y = rect.y; y < rect.y + rect.h; ++y) {
            for (let x = rect.x; x < rect.x + rect.w; ++x) {
                const i = (y * readback.width + x) * 4;
                for (let k = 0; k < 4; ++k)
                    sum[k] += readback.data[i + k];
            }
        }
        const n = rect.w * rect.h;
        return sum.map(v => v / n);
    }

    function formatValue(v)
    {
        return "(" + v.map(c => Math.round(c)).join(",") + ")";
    }

    // Compares the sampled patches with the expected values. Returns a list of mismatch strings
    // (empty when everything matches). options: tolerance, alphaTolerance.
    function comparePatches(readback, patches, options = { })
    {
        const tolerance = options.tolerance === undefined ? 3 : options.tolerance;
        const alphaTolerance = options.alphaTolerance === undefined ? Math.max(2, tolerance) : options.alphaTolerance;
        const failures = [];
        if (!patches.length)
            failures.push("no patch inside the drawn area");
        for (const patch of patches) {
            if (!patch.expected)
                continue;
            const observed = samplePatch(readback, patch.rect);
            let bad = false;
            if (patch.checkColor) {
                for (let k = 0; k < 3; ++k)
                    bad = bad || Math.abs(observed[k] - patch.expected[k]) > tolerance;
            }
            bad = bad || Math.abs(observed[3] - patch.expected[3]) > alphaTolerance;
            if (bad) {
                const expected = patch.checkColor ? formatValue(patch.expected) : `(*,*,*,${patch.expected[3]})`;
                failures.push(`${patch.cell} at ${patch.rect.x},${patch.rect.y}: ${formatValue(observed)}, expected ${expected}`);
            }
        }
        return failures;
    }

    // Checks that every pixel of the readback outside `rect` (clipped) has `color` within tolerance.
    // Returns a failure string or null.
    function compareOutside(readback, rect, color, tolerance = 2)
    {
        let count = 0;
        let first = null;
        for (let y = 0; y < readback.height; ++y) {
            for (let x = 0; x < readback.width; ++x) {
                if (rect && x >= rect.x && x < rect.x + rect.w && y >= rect.y && y < rect.y + rect.h)
                    continue;
                const i = (y * readback.width + x) * 4;
                for (let k = 0; k < 4; ++k) {
                    if (Math.abs(readback.data[i + k] - color[k]) > tolerance) {
                        if (!first)
                            first = `${x},${y} ${formatValue(Array.from(readback.data.slice(i, i + 4)))}`;
                        ++count;
                        break;
                    }
                }
            }
        }
        if (!count)
            return null;
        return `${count} pixels outside the image differ from ${formatValue(color)}, first at ${first}`;
    }

    // Finds the transform of the pattern drawn into `region` of the readback by matching the four
    // corner patches. Returns a transform name or "unknown".
    function detectTransform(readback, info, region)
    {
        const layout = layoutOf(info);
        region = region || { x: 0, y: 0, w: readback.width, h: readback.height };
        const corners = layout.cells.filter(cell => ["red", "green", "blue", "white"].includes(cell.name));
        let best = null;
        for (const transform of transformNames) {
            const size = transformedSize(transform, layout.width, layout.height);
            if (Math.abs(size.width / size.height - region.w / region.h) > 0.02)
                continue;
            const scaleX = region.w / size.width;
            const scaleY = region.h / size.height;
            let error = 0;
            for (const cell of corners) {
                const p = mapPoint(transform, layout.width, layout.height, cell.x + cell.w / 2, cell.y + cell.h / 2);
                const x = Math.floor(region.x + p.x * scaleX) - 2;
                const y = Math.floor(region.y + p.y * scaleY) - 2;
                const v = samplePatch(readback, { x, y, w: 4, h: 4 });
                const target = manifest.colors[cell.name];
                error += Math.abs(v[0] - target[0]) + Math.abs(v[1] - target[1]) + Math.abs(v[2] - target[2]);
            }
            if (!best || error < best.error)
                best = { error, transform };
        }
        if (!best || best.error > 4 * 3 * 60)
            return "unknown";
        return best.transform;
    }

    // Reads the frame counter bits of a pattern drawn with `options` (as for expectedPatches).
    function frameCounter(readback, info, options = { })
    {
        const patches = expectedPatches(info, Object.assign({ }, options, { colorSpace: "native", frame: 0 }));
        let counter = 0;
        let found = 0;
        for (const patch of patches) {
            if (!patch.cell.startsWith("bit"))
                continue;
            const v = samplePatch(readback, patch.rect);
            if ((v[0] + v[1] + v[2]) / 3 > 128)
                counter |= 1 << Number(patch.cell.substring(3));
            ++found;
        }
        return found === 3 ? counter : null;
    }

    // ---- Mock camera ----

    // The mock camera (MockRealtimeVideoSource::drawBoxes) draws a row of seven boxes below the
    // vertical centre, starting at the left: white, yellow, cyan, dark green, magenta, red, blue.
    // In a capture of width W and height H, boxSize = 0.035 W, the row's top is
    // 0.6 H + boxSize + 2 and box i covers x = boxSize + i (boxSize + 1) .. + boxSize + 1.
    const mockCameraBoxColors = [[255, 255, 255], [255, 255, 0], [0, 255, 255], [0, 128, 0], [255, 0, 255], [255, 0, 0], [0, 0, 255]];

    function mockCameraBoxes(width, height)
    {
        const boxSize = width * 0.035;
        const top = height * 0.6 + boxSize + 2;
        return mockCameraBoxColors.map((color, i) => {
            const left = boxSize + i * (boxSize + 1);
            return { color, x: left + (boxSize + 1) / 2, y: top + (boxSize + 1) / 2 };
        });
    }

    // Finds the transform of a mock camera frame drawn into `region` (default: the whole readback):
    // the direction of the box row plus its side of the centre identify all 8 transforms. This is an
    // oracle independent of every sink. Returns {transform, maxDifference} where maxDifference is the
    // largest channel difference of a box, or {transform: "unknown"}.
    function detectMockCameraTransform(readback, region)
    {
        region = region || { x: 0, y: 0, w: readback.width, h: readback.height };
        let best = null;
        for (const transform of transformNames) {
            const source = transformedSize(transform, region.w, region.h);
            let error = 0;
            let maxDifference = 0;
            for (const box of mockCameraBoxes(source.width, source.height)) {
                const p = mapPoint(transform, source.width, source.height, box.x, box.y);
                const v = samplePatch(readback, { x: Math.floor(region.x + p.x) - 2, y: Math.floor(region.y + p.y) - 2, w: 4, h: 4 });
                for (let k = 0; k < 3; ++k) {
                    const d = Math.abs(v[k] - box.color[k]);
                    error += d;
                    maxDifference = Math.max(maxDifference, d);
                }
            }
            if (!best || error < best.error)
                best = { error, transform, maxDifference };
        }
        if (best.maxDifference > 100)
            return { transform: "unknown", maxDifference: best.maxDifference };
        return { transform: best.transform, maxDifference: best.maxDifference };
    }

    // The transform a mock camera frame should be displayed with after
    // testRunner.setMockCameraOrientation(angle): the frame carries rotation `angle` (clockwise).
    function mockCameraExpectedTransform(angle)
    {
        return angle ? "rotate" + angle : "none";
    }

    async function getMockCameraStream(angle, constraints)
    {
        if (window.testRunner)
            testRunner.setMockCameraOrientation(angle);
        return navigator.mediaDevices.getUserMedia({ video: constraints || { width: 640, height: 480 } });
    }

    // A VideoFrame from MediaStreamTrackProcessor (exposed only in dedicated workers): the track is
    // transferred to a worker, which posts back its second frame. The track is stopped there.
    async function trackProcessorFrame(track)
    {
        const script = `self.onmessage = async event => {
            const reader = new MediaStreamTrackProcessor({ track: event.data }).readable.getReader();
            let result = await reader.read();
            result.value.close();
            result = await reader.read();
            self.postMessage(result.value, [result.value]);
            reader.cancel();
            event.data.stop();
        };`;
        const url = URL.createObjectURL(new Blob([script], { type: "text/javascript" }));
        const worker = new Worker(url);
        URL.revokeObjectURL(url);
        const message = waitForEvent(worker, "message", 5000);
        worker.postMessage(track, [track]);
        const frame = (await message).data;
        worker.terminate();
        return frame;
    }

    // ---- WebCodecs ----

    // Decodes the video's chunks with VideoDecoder (chunk table from the manifest). Returns the
    // output VideoFrames in presentation order; the caller closes them.
    // options: data (the file's contents, if already fetched), chunks (decode only the first `chunks`
    // chunks; the first chunk is the key frame of frame 0).
    async function decodeFrames(name, config = { }, options = { })
    {
        const info = videoInfo(name);
        if (!info.decoderChunks)
            throw new Error(`${name} has no decoder chunk table`);
        const data = options.data || await fetchArrayBuffer(videoURL(name));
        const decoderConfig = Object.assign({ codec: info.codecString }, config);
        // Only H.264 and HEVC get a description. An AV1 av1C description hits
        // ASSERT(type == VideoCodecType::H265) in videoInfoFromFormatDescription
        // (WebKit/WebProcess/GPU/webrtc/LibWebRTCCodecs.cpp) in debug builds; it is optional for AV1.
        if (info.decoderDescription && (info.codec === "h264" || info.codec === "hevc"))
            decoderConfig.description = data.slice(info.decoderDescription[0], info.decoderDescription[0] + info.decoderDescription[1]);
        const support = await VideoDecoder.isConfigSupported(decoderConfig);
        if (!support.supported)
            throw new Error(`VideoDecoder does not support ${info.codecString}`);
        const frames = [];
        let error = null;
        const decoder = new VideoDecoder({ output: frame => frames.push(frame), error: e => { error = e; } });
        decoder.configure(decoderConfig);
        for (const [offset, size, key, timestamp] of options.chunks ? info.decoderChunks.slice(0, options.chunks) : info.decoderChunks)
            decoder.decode(new EncodedVideoChunk({ type: key ? "key" : "delta", timestamp, data: data.slice(offset, offset + size) }));
        await decoder.flush();
        decoder.close();
        if (error)
            throw error;
        frames.sort((a, b) => a.timestamp - b.timestamp);
        return frames;
    }

    // Exact JS-built frames: a one-pixel luma ruler. Y = x along the top row,
    // Y = 255 - x along the bottom row, Y = y down the left column, Y = 255 - y down the right
    // column, 128 inside; chroma 128, full range, so R = G = B = Y with every matrix.
    function rulerLuma(width, height, x, y)
    {
        if (y === 0)
            return x;
        if (y === height - 1)
            return 255 - x;
        if (x === 0)
            return y;
        if (x === width - 1)
            return 255 - y;
        return 128;
    }

    const rulerColorSpace = { primaries: "bt709", transfer: "iec61966-2-1", matrix: "bt709", fullRange: true };

    function createRulerFrame(format, width, height, timestamp = 0)
    {
        const lumaSize = width * height;
        const chromaWidth = width / 2;
        const chromaHeight = height / 2;
        let data;
        const luma = new Uint8Array(lumaSize);
        for (let y = 0; y < height; ++y) {
            for (let x = 0; x < width; ++x)
                luma[y * width + x] = rulerLuma(width, height, x, y);
        }
        if (format === "NV12") {
            data = new Uint8Array(lumaSize + chromaWidth * chromaHeight * 2);
            data.set(luma);
            data.fill(128, lumaSize);
        } else if (format === "I420" || format === "I420A") {
            const chroma = chromaWidth * chromaHeight * 2;
            data = new Uint8Array(lumaSize + chroma + (format === "I420A" ? lumaSize : 0));
            data.set(luma);
            data.fill(128, lumaSize, lumaSize + chroma);
            if (format === "I420A")
                data.fill(255, lumaSize + chroma);
        } else {
            data = new Uint8Array(lumaSize * 4);
            for (let i = 0; i < lumaSize; ++i) {
                data[i * 4] = data[i * 4 + 1] = data[i * 4 + 2] = luma[i];
                data[i * 4 + 3] = 255;
            }
        }
        const init = { format, codedWidth: width, codedHeight: height, timestamp };
        if (["NV12", "I420", "I420A"].includes(format))
            init.colorSpace = rulerColorSpace;
        return new VideoFrame(data, init);
    }

    // ---- Colour range names, colour management and JS-built pattern frames ----

    // The colour range as named in the video file names: limited ("video") range or full range.
    function rangeName(range)
    {
        return { tv: "videorange", pc: "fullrange" }[range] ?? range;
    }

    const D65 = [0.3127, 0.3290];
    const PRIMARIES = {
        "bt709": [[0.640, 0.330], [0.300, 0.600], [0.150, 0.060]],
        "smpte170m": [[0.630, 0.340], [0.310, 0.595], [0.155, 0.070]],
        "smpte240m": [[0.630, 0.340], [0.310, 0.595], [0.155, 0.070]],
        "bt470bg": [[0.640, 0.330], [0.290, 0.600], [0.150, 0.060]],
        "bt2020": [[0.708, 0.292], [0.170, 0.797], [0.131, 0.046]],
        "smpte432": [[0.680, 0.320], [0.265, 0.690], [0.150, 0.060]],
    };
    const MANAGE_TARGETS = { srgb: "bt709", displayP3: "smpte432" };
    const SDR_VIDEO_TRANSFERS = ["bt709", "smpte170m", "bt2020-10", "bt2020-12", "smpte240m"];

    function invert3(m)
    {
        const [[a, b, c], [d, e, f], [g, h, i]] = m;
        const det = a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g);
        return [[(e * i - f * h) / det, (c * h - b * i) / det, (b * f - c * e) / det],
            [(f * g - d * i) / det, (a * i - c * g) / det, (c * d - a * f) / det],
            [(d * h - e * g) / det, (b * g - a * h) / det, (a * e - b * d) / det]];
    }

    function multiply3(a, b)
    {
        return [0, 1, 2].map(i => [0, 1, 2].map(j => a[i][0] * b[0][j] + a[i][1] * b[1][j] + a[i][2] * b[2][j]));
    }

    function rgbToXyz(primaries)
    {
        const cols = PRIMARIES[primaries].map(([x, y]) => [x / y, 1, (1 - x - y) / y]);
        const m = [0, 1, 2].map(i => [0, 1, 2].map(j => cols[j][i]));
        const w = [D65[0] / D65[1], 1, (1 - D65[0] - D65[1]) / D65[1]];
        const inv = invert3(m);
        const s = [0, 1, 2].map(i => inv[i][0] * w[0] + inv[i][1] * w[1] + inv[i][2] * w[2]);
        return m.map(row => row.map((v, j) => v * s[j]));
    }

    function srgbDecode(v)
    {
        return v <= 0.04045 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
    }

    function srgbEncode(v)
    {
        return v <= 0.0031308 ? 12.92 * v : 1.055 * Math.pow(v, 1 / 2.4) - 0.055;
    }

    // Decodes a transfer function as the manifest's colour-managed values do (the generator's model
    // of the platform: SDR video transfers as manifest.sdrVideoTransferModel, i.e. a pure 1.961 power).
    function transferDecode(transfer, v)
    {
        if (transfer === "iec61966-2-1")
            return srgbDecode(v);
        if (SDR_VIDEO_TRANSFERS.includes(transfer)) {
            if (manifest.sdrVideoTransferModel === "srgb")
                return srgbDecode(v);
            return Math.pow(v, 1.961);
        }
        if (transfer === "linear")
            return v;
        throw new Error("no colour-managed model for transfer " + transfer);
    }

    // Colour-manages 8-bit-scale native R'G'B' from (primaries, transfer) into target
    // ("srgb" | "displayP3"), clipped, as the generator computes the manifest's srgb/displayP3 values.
    function manageColor(native, primaries, transfer, target)
    {
        const m = multiply3(invert3(rgbToXyz(MANAGE_TARGETS[target])), rgbToXyz(primaries));
        const linear = native.map(c => transferDecode(transfer, Math.max(0, Math.min(1, c / 255))));
        return [0, 1, 2].map(i => srgbEncode(Math.max(0, Math.min(1, m[i][0] * linear[0] + m[i][1] * linear[1] + m[i][2] * linear[2]))) * 255);
    }

    const MATRIX_K = { "bt709": [0.2126, 0.0722], "bt470bg": [0.299, 0.114], "smpte170m": [0.299, 0.114], "bt2020-ncl": [0.2627, 0.0593] };

    // 8-bit Y'CbCr of an 8-bit R'G'B' colour.
    function rgbToYCbCr(rgb, matrix, fullRange)
    {
        const [kr, kb] = MATRIX_K[matrix];
        const [r, g, b] = rgb.map(c => c / 255);
        const y = kr * r + (1 - kr - kb) * g + kb * b;
        const cb = (b - y) / (2 * (1 - kb));
        const cr = (r - y) / (2 * (1 - kr));
        const clamp = v => Math.max(0, Math.min(255, Math.round(v)));
        if (fullRange)
            return [clamp(y * 255), clamp(128 + cb * 255), clamp(128 + cr * 255)];
        return [clamp(16 + 219 * y), clamp(128 + 224 * cb), clamp(128 + 224 * cr)];
    }

    // 8-bit-scale R'G'B' (floats, clipped) of an 8-bit Y'CbCr value.
    function yCbCrToRgb(ycc, matrix, fullRange)
    {
        const [kr, kb] = MATRIX_K[matrix];
        const y = fullRange ? ycc[0] / 255 : (ycc[0] - 16) / 219;
        const cb = fullRange ? (ycc[1] - 128) / 255 : (ycc[1] - 128) / 224;
        const cr = fullRange ? (ycc[2] - 128) / 255 : (ycc[2] - 128) / 224;
        const r = y + 2 * (1 - kr) * cr;
        const b = y + 2 * (1 - kb) * cb;
        const g = (y - kr * r - kb * b) / (1 - kr - kb);
        return [r, g, b].map(c => Math.max(0, Math.min(1, c)) * 255);
    }

    const PATTERN_YUV_FORMATS = ["NV12", "I420", "I420A"];

    // The default colour space of a JS-built frame of `format` in createPatternFrame.
    function defaultPatternColorSpace(format)
    {
        if (PATTERN_YUV_FORMATS.includes(format))
            return { primaries: "bt709", transfer: "iec61966-2-1", matrix: "bt709", fullRange: true };
        return { primaries: "bt709", transfer: "iec61966-2-1", matrix: "rgb", fullRange: true };
    }

    // A pattern info object for a JS-built frame, in the shape of a manifest video entry, so that
    // expectedPatches() and the checks work on it. Native values are the pattern colours after the
    // 8-bit Y'CbCr round trip (YUV formats) or exact (RGB formats); srgb/displayP3 are colour-managed
    // from the frame's colour space as manageColor() computes them.
    // options: colorSpace (VideoColorSpaceInit, default defaultPatternColorSpace(format)), alpha
    // (default: true for I420A, RGBA and BGRA), label.
    function patternFrameInfo(format, options = { })
    {
        const colorSpace = Object.assign(defaultPatternColorSpace(format), options.colorSpace || { });
        const yuv = PATTERN_YUV_FORMATS.includes(format);
        const alpha = options.alpha !== undefined ? options.alpha : ["I420A", "RGBA", "BGRA"].includes(format);
        const layout = manifest.layouts.v3;
        const colors = { };
        for (const [color, rgb] of Object.entries(manifest.colors)) {
            const native = yuv ? yCbCrToRgb(rgbToYCbCr(rgb, colorSpace.matrix, colorSpace.fullRange), colorSpace.matrix, colorSpace.fullRange) : rgb.slice();
            colors[color] = {
                native,
                srgb: manageColor(native, colorSpace.primaries, colorSpace.transfer, "srgb"),
                displayP3: manageColor(native, colorSpace.primaries, colorSpace.transfer, "displayP3"),
                nativeInDisplayP3: manageColor(native, "bt709", "iec61966-2-1", "displayP3"),
            };
        }
        return {
            file: options.label || `${format} pattern`,
            layout: "v3",
            width: layout.width,
            height: layout.height,
            displayWidth: layout.width,
            displayHeight: layout.height,
            transform: "none",
            alpha,
            bitDepth: 8,
            managed: "computed",
            matrix: colorSpace.matrix,
            range: colorSpace.fullRange ? "pc" : "tv",
            primaries: colorSpace.primaries,
            transfer: colorSpace.transfer,
            colorSpace,
            colors,
        };
    }

    // A JS-built VideoFrame with the pattern (320x192, the bit patches showing options.frame).
    // format: NV12, I420, I420A, RGBA, RGBX, BGRA, BGRX. options as for patternFrameInfo, plus frame
    // (counter, default 0), timestamp and init (extra VideoFrameInit members, e.g. visibleRect).
    // Returns {frame, info}.
    function createPatternFrame(format, options = { })
    {
        const info = patternFrameInfo(format, options);
        const layout = manifest.layouts.v3;
        const width = layout.width;
        const height = layout.height;
        const colorSpace = info.colorSpace;
        const yuv = PATTERN_YUV_FORMATS.includes(format);
        const cellAt = new Array(width * height);
        for (const cell of layout.cells) {
            for (let y = cell.y; y < cell.y + cell.h; ++y) {
                for (let x = cell.x; x < cell.x + cell.w; ++x)
                    cellAt[y * width + x] = cell.name;
            }
        }
        const colorOf = i => cellColor(cellAt[i], options.frame || 0);
        const alphaOf = i => info.alpha ? cellAlpha({ alpha: true }, cellAt[i]) : 255;
        let data;
        if (yuv) {
            const lumaSize = width * height;
            const chromaWidth = width / 2;
            const chromaSize = chromaWidth * (height / 2);
            data = new Uint8Array(lumaSize + 2 * chromaSize + (format === "I420A" ? lumaSize : 0));
            const ycc = { };
            for (const [color, rgb] of Object.entries(manifest.colors))
                ycc[color] = rgbToYCbCr(rgb, colorSpace.matrix, colorSpace.fullRange);
            for (let i = 0; i < lumaSize; ++i) {
                data[i] = ycc[colorOf(i)][0];
                if (format === "I420A")
                    data[lumaSize + 2 * chromaSize + i] = alphaOf(i);
            }
            for (let cy = 0; cy < height / 2; ++cy) {
                for (let cx = 0; cx < chromaWidth; ++cx) {
                    const v = ycc[colorOf(2 * cy * width + 2 * cx)];
                    const c = cy * chromaWidth + cx;
                    if (format === "NV12") {
                        data[lumaSize + 2 * c] = v[1];
                        data[lumaSize + 2 * c + 1] = v[2];
                    } else {
                        data[lumaSize + c] = v[1];
                        data[lumaSize + chromaSize + c] = v[2];
                    }
                }
            }
        } else {
            data = new Uint8Array(width * height * 4);
            const bgr = format.startsWith("BGR");
            const opaque = format.endsWith("X");
            for (let i = 0; i < width * height; ++i) {
                const rgb = manifest.colors[colorOf(i)];
                data[i * 4] = bgr ? rgb[2] : rgb[0];
                data[i * 4 + 1] = rgb[1];
                data[i * 4 + 2] = bgr ? rgb[0] : rgb[2];
                data[i * 4 + 3] = opaque ? 255 : alphaOf(i);
            }
        }
        const init = Object.assign({ format, codedWidth: width, codedHeight: height, timestamp: options.timestamp || 0, colorSpace }, options.init || { });
        return { frame: new VideoFrame(data, init), info };
    }

    return {
        manifest,
        TRANSFORMS,
        transformNames,
        composeTransforms,
        transformFromRotationAndFlip,
        transformedSize,
        mapRect,
        intersect,
        videoInfo,
        videoNames,
        videoURL,
        layoutOf,
        defaultTolerance,
        fetchArrayBuffer,
        waitForEvent,
        waitForVideoFrame,
        waitForStableFrame,
        loadVideo,
        releaseVideo,
        seekToFrame,
        expectedPatches,
        samplePatch,
        comparePatches,
        compareOutside,
        formatValue,
        detectTransform,
        frameCounter,
        mockCameraBoxes,
        detectMockCameraTransform,
        mockCameraExpectedTransform,
        getMockCameraStream,
        trackProcessorFrame,
        decodeFrames,
        rulerLuma,
        createRulerFrame,
        rangeName,
        manageColor,
        patternFrameInfo,
        createPatternFrame,
    };
})();
